-- ============================================================================
-- KeyNexus 데모 시드 데이터
-- ============================================================================
-- 사용자 8명(로그인 계정), 프로젝트 8개, 자산 26개, 접근신청/승인 이력, 감사로그.
-- 모든 데모 계정 비밀번호: password123
--
-- courses.metadata 는 CREDENTIAL_ENCRYPTION_KEY 로 암호화된 Secret 이다.
-- 이 시드의 암호문은 .env.example 에 고정된 데모 키 기준으로 만들어졌다.
-- 다른 키를 쓰면 자산 상세의 "Secret 표시"가 복호화 실패한다(그 외 기능은 정상).
--
-- 적용:
--   - 신규 볼륨: init-db/*.sql 이 01→02→03 순으로 자동 실행됨 (별도 작업 불필요)
--   - 기존 볼륨(자동 실행 안 됨): 아래 명령으로 수동 적용 (DELETE 후 재삽입이라 재실행 안전)
--       docker exec -i lecturedb mariadb -umanager -pSqlDba-1 lecture_db < init-db/03_seed_demo.sql
--   - 데모 데이터가 필요 없으면 이 파일을 지우고 볼륨을 초기화한다.
-- ============================================================================

SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM credential_audit_logs;
DELETE FROM payments;
DELETE FROM enrollments;
DELETE FROM courses;
DELETE FROM projects;
DELETE FROM users;


SET FOREIGN_KEY_CHECKS = 1;
